#!/usr/bin/env python3
"""FS3 v186 - weapon banks, weapon energy, the new top bar.

    Arsenal     The player flies FreeSpace's weapons now: Prometheus R and
                S, Subach and Mekhu HL-7, Akheton, Morning Star, Kayser,
                Lamprey, Circe, Maxim, plus the Sidhe and the Dante; Harpoon,
                Rockeye, Tempest, Hornet, Tornado, EMP, Infyrno, Trebuchet,
                Piranha, Stiletto II, TAG-C, Cyclops, Helios. FS2 ratios,
                anchored on the old Prometheus, MX-64 and Cyclops. The AI
                keeps its weapons until its own step.
    Banks       Up to two primary and three secondary banks per hull, the
                default fit from ships.tbl. Wheel up / Q: bank 1, bank 2,
                linked. Wheel down / E: next secondary bank. Every rack has
                its own ammunition.
    Energy      A weapon store per hull; on the Myrmidon one bank never
                runs dry, both linked last about ten seconds.
    Rearm       Until the loadout screen: one row per bank, a tap switches
                it to the next weapon the hull may carry (more by points).
    Missions    M57 puts a Stiletto II into bank 1, M67/M72 a TAG-C into the
                last bank.
    Bar         Variant A, 54 high: three stores, the banks, support,
                tickets, and V R M S P as five buttons of one kind with the
                new icons.

Needs v185. Edits src/30_waves.js to src/70_ui.js in place, adds
src/56_banks.js and writes the updated simulations. Run assemble.py
afterwards.
"""
import base64
import os
import sys

if "SMALL_TBL" not in open("src/30_waves.js", encoding="utf-8").read():
    sys.exit("Abbruch: erst v185 einspielen.")
if os.path.exists("src/56_banks.js"):
    sys.exit("Abbruch: v186 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
